from __future__ import annotations

import json
import sys
from pathlib import Path
from typing import Any

import numpy as np
import torch

TASK_DIR = Path(__file__).resolve().parent
SOURCE_DIR = TASK_DIR / "source"
OUTPUT_DIR = TASK_DIR / "outputs"

sys.path.insert(0, str(SOURCE_DIR))

from deepmd.dpmodel.model.spin_model import SpinModel as NumpySpinModel  # noqa: E402
from deepmd.pt.model.model.spin_model import SpinModel as TorchSpinModel  # noqa: E402
from deepmd.utils.spin import Spin  # noqa: E402


class _DummyNpBackbone:
    def get_dp_atomic_model(self) -> None:
        return None


class _DummyTorchBackbone(torch.nn.Module):
    def __init__(self) -> None:
        super().__init__()


def _build_model(backend: str) -> NumpySpinModel | TorchSpinModel:
    spin = Spin(use_spin=[True, False, True], virtual_scale=[0.5, 0.0, 0.75])
    if backend == "numpy":
        return NumpySpinModel(_DummyNpBackbone(), spin)
    return TorchSpinModel(_DummyTorchBackbone(), spin)


def _to_backend(array: np.ndarray, backend: str) -> Any:
    if backend == "torch":
        dtype = torch.long if np.issubdtype(array.dtype, np.integer) else torch.float64
        return torch.tensor(array, dtype=dtype)
    return array.copy()


def _clone(value: Any, backend: str) -> Any:
    if backend == "torch":
        return value.clone()
    return value.copy()


def _max_abs_delta(lhs: Any, rhs: Any, backend: str) -> float:
    if backend == "torch":
        return float(torch.max(torch.abs(lhs - rhs)).item())
    return float(np.max(np.abs(lhs - rhs)))


def _set_vectors(array: Any, indices: list[int], values: list[list[float]], backend: str) -> None:
    for index, value in zip(indices, values, strict=True):
        if backend == "torch":
            array[0, index] = torch.tensor(value, dtype=array.dtype, device=array.device)
        else:
            array[0, index] = np.array(value, dtype=array.dtype)


def _dense_fixture(name: str) -> dict[str, Any]:
    if name == "middle":
        return {
            "coord": np.array(
                [[[0.0, 0.1, 0.2], [1.0, 1.1, 1.2], [2.0, 2.1, 2.2]]],
                dtype=np.float64,
            ),
            "atype": np.array([[0, -1, 2]], dtype=np.int64),
            "background_positions": [1],
            "signal_position": 2,
        }
    return {
        "coord": np.array(
            [
                [
                    [0.0, 0.1, 0.2],
                    [1.0, 1.1, 1.2],
                    [2.0, 2.1, 2.2],
                    [3.0, 3.1, 3.2],
                ]
            ],
            dtype=np.float64,
        ),
        "atype": np.array([[2, 1, 0, -1]], dtype=np.int64),
        "background_positions": [3],
        "signal_position": 0,
    }


def _lower_fixture() -> dict[str, Any]:
    return {
        "coord": np.array(
            [
                [
                    [0.0, 0.1, 0.2],
                    [1.0, 1.1, 1.2],
                    [2.0, 2.1, 2.2],
                    [3.0, 3.1, 3.2],
                ]
            ],
            dtype=np.float64,
        ),
        "atype": np.array([[0, -1, 2, -1]], dtype=np.int64),
        "background_positions": [1, 3],
        "signal_position": 0,
        "nlist": np.array([[[2, -1], [0, -1]]], dtype=np.int64),
        "mapping": np.array([[0, 1, 0, 1]], dtype=np.int64),
    }


def _dense_virtual_index(position: int, nloc: int) -> int:
    return nloc + position


def _lower_virtual_index(position: int, nloc: int, nall: int) -> int:
    if position < nloc:
        return nloc + position
    return nloc + nall + (position - nloc)


def _input_response_dense(
    model: NumpySpinModel | TorchSpinModel,
    backend: str,
    fixture: dict[str, Any],
) -> dict[str, float]:
    coord = _to_backend(fixture["coord"], backend)
    atype = _to_backend(fixture["atype"], backend)
    spin_base = _to_backend(np.zeros_like(fixture["coord"]), backend)
    spin_background = _clone(spin_base, backend)
    spin_signal = _clone(spin_base, backend)

    _set_vectors(
        spin_background,
        fixture["background_positions"],
        [[0.3, -0.2, 0.4] for _ in fixture["background_positions"]],
        backend,
    )
    _set_vectors(spin_signal, [fixture["signal_position"]], [[-0.4, 0.5, -0.6]], backend)

    coord_base, _, corr_base = model.process_spin_input(
        _clone(coord, backend), _clone(atype, backend), _clone(spin_base, backend)
    )
    coord_background, _, corr_background = model.process_spin_input(
        _clone(coord, backend), _clone(atype, backend), _clone(spin_background, backend)
    )
    coord_signal, _, corr_signal = model.process_spin_input(
        _clone(coord, backend), _clone(atype, backend), _clone(spin_signal, backend)
    )

    return {
        "background_response_max_abs": max(
            _max_abs_delta(coord_base, coord_background, backend),
            _max_abs_delta(corr_base, corr_background, backend),
        ),
        "signal_response_max_abs": max(
            _max_abs_delta(coord_base, coord_signal, backend),
            _max_abs_delta(corr_base, corr_signal, backend),
        ),
    }


def _input_response_lower(
    model: NumpySpinModel | TorchSpinModel,
    backend: str,
    fixture: dict[str, Any],
) -> dict[str, float]:
    coord = _to_backend(fixture["coord"], backend)
    atype = _to_backend(fixture["atype"], backend)
    nlist = _to_backend(fixture["nlist"], backend)
    mapping = _to_backend(fixture["mapping"], backend)
    spin_base = _to_backend(np.zeros_like(fixture["coord"]), backend)
    spin_background = _clone(spin_base, backend)
    spin_signal = _clone(spin_base, backend)

    _set_vectors(
        spin_background,
        fixture["background_positions"],
        [[0.3, -0.2, 0.4], [-0.7, 0.8, -0.9]],
        backend,
    )
    _set_vectors(spin_signal, [fixture["signal_position"]], [[-0.4, 0.5, -0.6]], backend)

    coord_base, _, _, _, corr_base = model.process_spin_input_lower(
        _clone(coord, backend),
        _clone(atype, backend),
        _clone(spin_base, backend),
        _clone(nlist, backend),
        mapping=_clone(mapping, backend),
    )
    coord_background, _, _, _, corr_background = model.process_spin_input_lower(
        _clone(coord, backend),
        _clone(atype, backend),
        _clone(spin_background, backend),
        _clone(nlist, backend),
        mapping=_clone(mapping, backend),
    )
    coord_signal, _, _, _, corr_signal = model.process_spin_input_lower(
        _clone(coord, backend),
        _clone(atype, backend),
        _clone(spin_signal, backend),
        _clone(nlist, backend),
        mapping=_clone(mapping, backend),
    )

    return {
        "background_response_max_abs": max(
            _max_abs_delta(coord_base, coord_background, backend),
            _max_abs_delta(corr_base, corr_background, backend),
        ),
        "signal_response_max_abs": max(
            _max_abs_delta(coord_base, coord_signal, backend),
            _max_abs_delta(corr_base, corr_signal, backend),
        ),
    }


def _output_response_dense(
    model: NumpySpinModel | TorchSpinModel,
    backend: str,
    fixture: dict[str, Any],
    *,
    use_scale_weight: bool,
) -> dict[str, float]:
    atype = _to_backend(fixture["atype"], backend)
    nloc = fixture["atype"].shape[1]
    out_base = _to_backend(np.ones((1, 2 * nloc, 3), dtype=np.float64), backend)
    out_background = _clone(out_base, backend)
    out_signal = _clone(out_base, backend)
    background_indices = [
        _dense_virtual_index(position, nloc) for position in fixture["background_positions"]
    ]
    signal_index = _dense_virtual_index(fixture["signal_position"], nloc)

    _set_vectors(
        out_background,
        background_indices,
        [[0.25, -0.5, 1.25] for _ in background_indices],
        backend,
    )
    _set_vectors(out_signal, [signal_index], [[-1.5, 0.75, 0.5]], backend)

    _, mag_base, _ = model.process_spin_output(
        _clone(atype, backend), _clone(out_base, backend), virtual_scale=use_scale_weight
    )
    _, mag_background, _ = model.process_spin_output(
        _clone(atype, backend),
        _clone(out_background, backend),
        virtual_scale=use_scale_weight,
    )
    _, mag_signal, _ = model.process_spin_output(
        _clone(atype, backend), _clone(out_signal, backend), virtual_scale=use_scale_weight
    )
    return {
        "background_response_max_abs": _max_abs_delta(mag_base, mag_background, backend),
        "signal_response_max_abs": _max_abs_delta(mag_base, mag_signal, backend),
    }


def _output_response_lower(
    model: NumpySpinModel | TorchSpinModel,
    backend: str,
    fixture: dict[str, Any],
    *,
    use_scale_weight: bool,
) -> dict[str, float]:
    atype = _to_backend(fixture["atype"], backend)
    nall = fixture["atype"].shape[1]
    nloc = fixture["nlist"].shape[1]
    out_base = _to_backend(np.ones((1, 2 * nall, 3), dtype=np.float64), backend)
    out_background = _clone(out_base, backend)
    out_signal = _clone(out_base, backend)
    background_indices = [
        _lower_virtual_index(position, nloc, nall)
        for position in fixture["background_positions"]
    ]
    signal_index = _lower_virtual_index(fixture["signal_position"], nloc, nall)

    _set_vectors(
        out_background,
        background_indices,
        [[0.25, -0.5, 1.25], [-1.25, 0.5, -0.25]],
        backend,
    )
    _set_vectors(out_signal, [signal_index], [[-1.5, 0.75, 0.5]], backend)

    _, mag_base, _ = model.process_spin_output_lower(
        _clone(atype, backend),
        _clone(out_base, backend),
        nloc=nloc,
        virtual_scale=use_scale_weight,
    )
    _, mag_background, _ = model.process_spin_output_lower(
        _clone(atype, backend),
        _clone(out_background, backend),
        nloc=nloc,
        virtual_scale=use_scale_weight,
    )
    _, mag_signal, _ = model.process_spin_output_lower(
        _clone(atype, backend),
        _clone(out_signal, backend),
        nloc=nloc,
        virtual_scale=use_scale_weight,
    )
    return {
        "background_response_max_abs": _max_abs_delta(mag_base, mag_background, backend),
        "signal_response_max_abs": _max_abs_delta(mag_base, mag_signal, backend),
    }


def _scenario_observation(
    model: NumpySpinModel | TorchSpinModel,
    backend: str,
    layout: str,
    fixture: dict[str, Any],
) -> dict[str, Any]:
    if layout == "dense":
        input_response = _input_response_dense(model, backend, fixture)
        output_response = {
            "weighted": _output_response_dense(
                model, backend, fixture, use_scale_weight=True
            ),
            "presence": _output_response_dense(
                model, backend, fixture, use_scale_weight=False
            ),
        }
    else:
        input_response = _input_response_lower(model, backend, fixture)
        output_response = {
            "weighted": _output_response_lower(
                model, backend, fixture, use_scale_weight=True
            ),
            "presence": _output_response_lower(
                model, backend, fixture, use_scale_weight=False
            ),
        }
    return {"input": input_response, "output": output_response}


def _flatten_response_values(observations: dict[str, Any], field: str) -> list[float]:
    values: list[float] = []
    for scenario in observations.values():
        values.append(float(scenario["input"][field]))
        for mode in scenario["output"].values():
            values.append(float(mode[field]))
    return values


def _status_from_observations(observations: dict[str, Any]) -> str:
    background_values = _flatten_response_values(
        observations, "background_response_max_abs"
    )
    signal_values = _flatten_response_values(observations, "signal_response_max_abs")
    if not all(np.isfinite(background_values + signal_values)):
        return "runner_failure"
    if max(background_values) > 0.0:
        return "pre_fix_expected_failure"
    if min(signal_values) > 0.0:
        return "post_fix_success"
    return "workflow_completed"


def run_workflow() -> dict[str, Any]:
    observations: dict[str, Any] = {}
    for backend in ("numpy", "torch"):
        model = _build_model(backend)
        for dense_name in ("middle", "tail"):
            observations[f"{backend}_dense_{dense_name}"] = _scenario_observation(
                model, backend, "dense", _dense_fixture(dense_name)
            )
        observations[f"{backend}_lower"] = _scenario_observation(
            model, backend, "lower", _lower_fixture()
        )

    background_values = _flatten_response_values(
        observations, "background_response_max_abs"
    )
    signal_values = _flatten_response_values(observations, "signal_response_max_abs")
    return {
        "status": _status_from_observations(observations),
        "summary": {
            "scenario_count": len(observations),
            "max_background_response": max(background_values),
            "min_signal_response": min(signal_values),
            "output_modes": ["weighted", "presence"],
        },
        "observations": observations,
    }


def main() -> int:
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    report_path = OUTPUT_DIR / "report.json"
    try:
        report = run_workflow()
        report_path.write_text(json.dumps(report, indent=2), encoding="utf-8")
        print(json.dumps(report, indent=2))
        return 1 if report["status"] == "runner_failure" else 0
    except Exception as exc:  # pragma: no cover - runner fallback
        report = {
            "status": "runner_failure",
            "error_type": type(exc).__name__,
            "error": str(exc),
        }
        report_path.write_text(json.dumps(report, indent=2), encoding="utf-8")
        print(json.dumps(report, indent=2))
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

